// TypeScript Version: 4.1

/**
* Interface describing a results object.
*/
interface Results {
	/**
	* Number of times the data was clustered with different initial centroids.
	*/
	replicates: number;

	/**
	* Index of the initial centroids which produced the best result.
	*/
	replicate: number;

	/**
	* Distance metric.
	*/
	metric: string;

	/**
	* Number of iterations for best results.
	*/
	iterations: number;

	/**
	* Clustering algorithm.
	*/
	algorithm: string;

	/**
	* Sum of squared distances to the closest centroid for all samples.
	*/
	inertia: number;

	/**
	* Number of clusters.
	*/
	k: number;

	/**
	* Number of samples.
	*/
	samples: number;

	/**
	* Number of features.
	*/
	features: number;

	/**
	* Clustering method.
	*/
	method: string;
}

/**
* Interface describing function options.
*/
interface Options {
	/**
	* Number of digits to display after decimal points. Default: 4.
	*/
	digits?: number;
}

/**
* Serializes a k-means clustering results object as a formatted string.
*
* ## Notes
*
* -   Example output:
*
*     ```text
*
*     K-means clustering using Lloyd algorithm
*
*         metric used: squared euclidean
*         total replicates: 4
*         best replicate: 2
*         total iterations: 10
*         inertia: 3.2800
*
*     Clustering ran for 4 clusters and 10 data samples, each with 3 features
*
*     ```
*
* @param results - k-means clustering results object
* @param options - options object
* @param options.digits - number of digits to display after decimal points
* @returns serialized results
*
* @example
* var results = {
*     'replicates': 4,
*     'replicate': 2,
*     'metric': 'sqeuclidean',
*     'iterations': 10,
*     'algorithm': 'lloyd',
*     'inertia': 3.28,
*     'k': 4,
*     'samples': 10,
*     'features': 3,
*     'method': 'K-means clustering'
* };
*
* var str = res2str( results );
* // returns <string>
*/
declare function res2str( results: Results, options?: Options ): string;


// EXPORTS //

export = res2str;
